import{_ as a,c as t,a2 as i,o as r}from"./chunks/framework.CoXjB5sU.js";const m=JSON.parse(`{"title":"What's new in ioChem-BD v5.0.0","description":"","frontmatter":{},"headers":[],"relativePath":"doc/whats-new.md","filePath":"doc/whats-new.md"}`),o={name:"doc/whats-new.md"};function n(s,e,l,d,c,h){return r(),t("div",null,e[0]||(e[0]=[i('<h1 id="what-s-new-in-iochem-bd-v5-0-0" tabindex="-1">What&#39;s new in ioChem-BD v5.0.0 <a class="header-anchor" href="#what-s-new-in-iochem-bd-v5-0-0" aria-label="Permalink to &quot;What&#39;s new in ioChem-BD v5.0.0&quot;">​</a></h1><p>ioChem-BD 5.0.0 is a major release that renews the whole platform: a brand-new public portal, centralized authentication, richer data publication and a guided installer. The previous documentation remains available at the <a href="https://docs.iochem-bd.org/v4/" target="_blank" rel="noreferrer">v4 legacy site</a>.</p><h2 id="new-browse-module-built-on-dspace-9" tabindex="-1">New Browse module built on DSpace 9 <a class="header-anchor" href="#new-browse-module-built-on-dspace-9" aria-label="Permalink to &quot;New Browse module built on DSpace 9&quot;">​</a></h2><p>The public portal has been rebuilt from scratch on <a href="https://www.dspace.org/" target="_blank" rel="noreferrer">DSpace 9</a>, replacing the previous interface with a modern web application:</p><ul><li><strong>Chemistry-aware search</strong>: results can be refined by program, method, basis set, energy, solvation, vibrations or orbitals</li><li><strong>Calculation pages</strong> with an interactive structure viewer (<em>View data</em>), direct geometry download and the complete metadata table</li><li><strong>Researcher profiles</strong> with ORCID iD and institutional affiliation</li><li><strong>Advanced statistics</strong> per researcher and published paper, in addition to portal, community and item usage</li><li>Read the <a href="./guides/usage/browse-module-walkthrough.html">Browse module walkthrough</a></li></ul><h2 id="centralized-sign-on" tabindex="-1">Centralized sign-on <a class="header-anchor" href="#centralized-sign-on" aria-label="Permalink to &quot;Centralized sign-on&quot;">​</a></h2><p>One account for the whole platform:</p><ul><li>Create and Browse share a single sign-on session</li><li>Users can provide their <strong>ORCID iD</strong> in their profile to retrieve their publishing data</li><li>Platform-wide end-user agreement and privacy policy pages</li></ul><h2 id="create-module" tabindex="-1">Create module <a class="header-anchor" href="#create-module" aria-label="Permalink to &quot;Create module&quot;">​</a></h2><p>The private working module gains several new capabilities:</p><ul><li><strong>Asset uploads</strong>: attach project documents, <a href="https://github.com/FairReactionData/RMMD" target="_blank" rel="noreferrer">RMMD</a> or JSON data sets to any project alongside calculations</li><li><strong>Molecular search</strong>: query by SMILES, InChI or InChIKey with contains/exact/similar matching, a structure editor and a periodic table element picker</li><li><strong>Redesigned publication workflow</strong>: a single six-section form with dataset type (independent or linked to manuscript), authors, sponsoring agencies, keywords, DOI request and embargo options</li><li><strong>Easier updates</strong>: appending new content to existing publications is now easier than before</li><li><strong>Publish reports</strong>: Supporting Information, Reaction Energy Profile and Reaction Graph reports are generated inside your projects and can be published to Browse like any other content</li><li><strong>Peer review support</strong>: embargoed publications generate reviewer links, with embargo management from the new <em>Edit published collection</em> page</li><li><strong>Supervision and collaboration</strong> integrated with the Browse administration: group membership, main group and supervisor roles are managed from the <em>Access Control</em> section</li></ul><h2 id="new-calculation-formats" tabindex="-1">New calculation formats <a class="header-anchor" href="#new-calculation-formats" aria-label="Permalink to &quot;New calculation formats&quot;">​</a></h2><p>The list of supported computational chemistry packages grows with <strong>CP2K</strong>, <strong>UMA</strong> (universal machine-learning potentials) and <strong>xTB</strong> on top of the existing ones. Check the <a href="/data/feature-matrix-table.html">Feature matrix</a> for the full coverage.</p><h2 id="deployment-and-administration" tabindex="-1">Deployment and administration <a class="header-anchor" href="#deployment-and-administration" aria-label="Permalink to &quot;Deployment and administration&quot;">​</a></h2><ul><li><strong>Guided installer</strong>: a text-interface installer with sensible defaults and an unattended mode replaces the manual deployment steps</li><li>Modern runtime: Java 21, PostgreSQL 14+, Apache Solr, Caddy reverse proxy with automatic HTTPS</li><li><strong>HTTPS certificate replacement</strong> simplified through the <em>replace-certificate.sh</em> script</li><li>Administration tasks (users, groups, communities) consolidated in the new Browse administration area</li></ul><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>This documentation site has been fully rewritten for v5. If you come from a v4 installation, the previous guides remain available at the <a href="https://docs.iochem-bd.org/v4/" target="_blank" rel="noreferrer">v4 legacy documentation</a>.</p>',17)]))}const p=a(o,[["render",n]]);export{m as __pageData,p as default};
